
(function(){const { $, read, write, uid, esc, money, date, today, notify }=window.OP;const KEY='np_flujo_caja_pymes_v1';let state=read(KEY,{transactions:[]});function persist(){write(KEY,state);render()}function render(){const t=state.transactions, income=t.filter(x=>x.type==='income').reduce((s,x)=>s+Number(x.amount),0),expense=t.filter(x=>x.type==='expense').reduce((s,x)=>s+Number(x.amount),0),pending=t.filter(x=>x.status==='pending').reduce((s,x)=>s+(x.type==='income'?1:-1)*Number(x.amount),0);$('[data-kpi="balance"]').textContent=money(income-expense);$('[data-kpi="income"]').textContent=money(income);$('[data-kpi="expense"]').textContent=money(expense);$('[data-kpi="pending"]').textContent=money(Math.abs(pending));const by={};t.forEach(x=>{by[x.category]=(by[x.category]||0)+(x.type==='income'?1:-1)*Number(x.amount)});$('#categorySummary').innerHTML=Object.keys(by).length?Object.entries(by).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).map(([k,v])=>`<div class="op-inline"><strong>${esc(k)}</strong><span class="op-tag ${v>=0?'good':'danger'}">${v>=0?'+':''}${money(v)}</span></div>`).join(''):'<div class="op-empty">Aún no hay categorías.</div>';const filter=$('#cashFilter').value;const rows=t.filter(x=>filter==='all'||x.type===filter||x.status===filter).sort((a,b)=>(a.due||'').localeCompare(b.due||''));$('#cashRows').innerHTML=rows.length?`<div class="op-table-wrap"><table class="op-table"><thead><tr><th>Fecha</th><th>Movimiento</th><th>Categoría</th><th>Importe</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${date(x.due)}</td><td><strong>${esc(x.description)}</strong><br><small>${esc(x.party||'')} ${x.notes?`· ${esc(x.notes)}`:''}</small></td><td>${esc(x.category)}</td><td class="${x.type==='income'?'op-good-text':'op-danger-text'}">${x.type==='income'?'+':'−'}${money(x.amount)}</td><td><button class="op-button" data-toggle="${x.id}"><span class="op-tag ${x.status==='paid'?'good':'warn'}">${x.status==='paid'?(x.type==='income'?'Cobrado':'Pagado'):'Pendiente'}</span></button></td><td><button class="op-button danger" data-delete="${x.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="op-empty">No hay movimientos para este filtro.</div>'}$('#cashForm').addEventListener('submit',e=>{e.preventDefault();const x={id:uid(),type:$('#cashType').value,status:$('#cashStatus').value,description:$('#cashDescription').value.trim(),amount:Number($('#cashAmount').value||0),category:$('#cashCategory').value,due:$('#cashDue').value||today(),party:$('#cashParty').value.trim(),notes:$('#cashNotes').value.trim(),createdAt:new Date().toISOString()};if(!x.description||x.amount<=0)return;state.transactions.unshift(x);e.target.reset();persist();notify('Movimiento guardado.','good')});$('#cashFilter').addEventListener('change',render);document.addEventListener('click',e=>{const toggle=e.target.closest('[data-toggle]')?.dataset.toggle;if(toggle){const x=state.transactions.find(v=>v.id===toggle);if(x){x.status=x.status==='paid'?'pending':'paid';persist()}}const del=e.target.closest('[data-delete]')?.dataset.delete;if(del&&confirm('¿Eliminar este movimiento?')){state.transactions=state.transactions.filter(x=>x.id!==del);persist()}});$('#clearCash').addEventListener('click',()=>{if(confirm('¿Eliminar todos los movimientos?')){state={transactions:[]};persist();notify('Registro de caja vacío.')}});render()})();